test('SUP-005 Friday 17:30 plus 120 business minutes is Monday 10:30 local',function(): void{$c=new Calendar(bCalendar('Europe/Istanbul',true));same('2026-10-26 07:30:00.000000',Time::format($c->deadline(Time::parse('2026-10-23 14:30:00'),120*Time::MINUTE)));});
test('SUP-005 explicit holiday pushes deadline to Tuesday and half-day is exact',function(): void{$p=bCalendar('Europe/Istanbul',true);$p['exceptions']['2026-10-26']=[];$c=new Calendar($p);same('2026-10-27 07:30:00.000000',Time::format($c->deadline(Time::parse('2026-10-23 14:30:00'),120*Time::MINUTE)));$p=bCalendar('UTC',true);$p['exceptions']['2026-10-23']=[['09:00','13:00']];same('2026-10-26 10:30:00.000000',Time::format((new Calendar($p))->deadline(Time::parse('2026-10-23 12:30:00'),120*Time::MINUTE)));});
test('SUP-005 DST spring skips nonexistent wall minutes without losing real UTC time',function(): void{$p=bCalendar('America/New_York');foreach($p['weekly'] as &$r){$r=[['01:00','04:00']];}unset($r);$c=new Calendar($p);$a=Time::parse('2026-03-08 06:00:00');$b=Time::parse('2026-03-08 08:00:00');same(120*Time::MINUTE,$c->elapsed($a,$b));same($b,$c->deadline($a,120*Time::MINUTE));});
test('SUP-005 DST fold counts each real UTC minute once and interval union avoids duplicates',function(): void{$p=bCalendar('America/New_York');foreach($p['weekly'] as &$r){$r=[['01:00','04:00'],['02:00','03:00']];}unset($r);$c=new Calendar($p);$a=Time::parse('2026-11-01 05:00:00');$b=Time::parse('2026-11-01 09:00:00');same(240*Time::MINUTE,$c->elapsed($a,$b));same($b,$c->deadline($a,240*Time::MINUTE));});
test('SUP-005 overnight shift and holiday override carry with half-open boundaries',function(): void{$p=bCalendar();foreach($p['weekly'] as &$r){$r=[];}unset($r);$p['weekly'][5]=[['22:00','02:00']];$c=new Calendar($p);same('2026-10-24 02:00:00.000000',Time::format($c->deadline(Time::parse('2026-10-23 23:00:00'),180*Time::MINUTE)));same(true,$c->working(Time::parse('2026-10-23 22:00:00')));same(false,$c->working(Time::parse('2026-10-24 02:00:00')));$p['exceptions']['2026-10-24']=[];same(120*Time::MINUTE,(new Calendar($p))->elapsed(Time::parse('2026-10-23 22:00:00'),Time::parse('2026-10-24 02:00:00')));});
test('SUP-005 microsecond precision and overlapping shifts use exact integer arithmetic',function(): void{$p=bCalendar();foreach($p['weekly'] as &$r){$r=[['09:00','12:00'],['11:00','13:00']];}unset($r);$c=new Calendar($p);same(240*Time::MINUTE,$c->elapsed(Time::parse('2026-10-26 09:00:00'),Time::parse('2026-10-26 13:00:00')));same('2026-10-26 09:01:00.123456',Time::format($c->deadline(Time::parse('2026-10-26 09:00:00.123456'),Time::MINUTE)));});
test('SUP-005 invalid calendars pause states and missing commercial targets fail closed',function(): void{$p=bCalendar();$p['timezone']='Invented/Timezone';raises(HttpError::class,fn()=>new Calendar($p));$p=bCalendar();$p['exceptions']['2026-02-30']=[];raises(HttpError::class,fn()=>new Calendar($p));$p=bPolicy();unset($p['targets']['LOW']);raises(HttpError::class,fn()=>Policy::validate($p));$p=bPolicy();$p['pause']['FIRST']=['WAITING_STAFF'];raises(HttpError::class,fn()=>Policy::validate($p));$p=bCalendar();foreach($p['weekly'] as &$r){$r=[];}unset($r);same('WORK_CALENDAR_HORIZON',raises(HttpError::class,fn()=>(new Calendar($p))->deadline(Time::parse('2026-10-25 00:00:00'),Time::MINUTE))->errorCode);});

test('SUP-005 held acknowledgement and internal note never count as actual first response',function(): void{$f=bFixture();$t=bTicket($f);$q=new Queue($f['db']);$o=new Outbox($f['db'],$q);while($o->dispatchOne()){}$w=new Worker($f['db'],$q);(new \Hostider\Commerce\EventSink($f['db']))->register($w);(new \Hostider\Support\EventSink($f['db'],$f['config']))->register($w);(new HeldSink($f['db'],$f['config']))->register($w);while($w->once()){}$before=bClocks($f,$t);same('RUNNING',$before[0]['status']);$out=$f['db']->execute('SELECT COUNT(*) FROM outbox_events')->fetchColumn();bReply($f,$t,'note');same($before,bClocks($f,$t));same($out,$f['db']->execute('SELECT COUNT(*) FROM outbox_events')->fetchColumn());bReply($f,$t);$first=array_values(array_filter(bClocks($f,$t),fn($c)=>$c['metric']==='FIRST'))[0];same('COMPLETED',$first['status']);same(true,$first['completed_at']!==null);});
test('SUP-005 each customer reply starts a next clock and genuine staff reply closes pending clocks',function(): void{$f=bFixture();$t=bTicket($f);bReply($f,$t);$initial=array_values(array_filter(bClocks($f,$t),fn($c)=>$c['metric']==='FIRST'))[0];bReply($f,$t,client:true);bReply($f,$t,client:true);same(2,count(array_filter(bClocks($f,$t),fn($c)=>$c['metric']==='NEXT'&&$c['status']==='RUNNING')));bReply($f,$t);same(2,count(array_filter(bClocks($f,$t),fn($c)=>$c['metric']==='NEXT'&&$c['status']==='COMPLETED')));same($initial,array_values(array_filter(bClocks($f,$t),fn($c)=>$c['metric']==='FIRST'))[0]);bReply($f,$t,client:true);same(1,count(array_filter(bClocks($f,$t),fn($c)=>$c['metric']==='NEXT'&&$c['status']==='RUNNING')));});
test('SUP-005 pause states are policy-specific and customer reply resumes resolution',function(): void{$f=bFixture();bHold($f);$old=bTicket($f);$p=bPolicy('MANUAL',['ON_HOLD','WAITING_CUSTOMER']);bPublish($f,$p);$new=bTicket($f);bState($f,$old,'ON_HOLD');bState($f,$new,'ON_HOLD');$metric=fn($rows)=>array_values(array_filter($rows,fn($r)=>$r['metric']==='RESOLUTION'))[0];same('RUNNING',$metric(bClocks($f,$old))['status']);same('PAUSED',$metric(bClocks($f,$new))['status']);same(null,$metric(bClocks($f,$new))['deadline_at']);bState($f,$new,'WAITING_STAFF');same('RUNNING',$metric(bClocks($f,$new))['status']);bReply($f,$new);same('PAUSED',$metric(bClocks($f,$new))['status']);bReply($f,$new,client:true);same('RUNNING',$metric(bClocks($f,$new))['status']);});
test('SUP-005 paused duration is not consumed while nonpaused first response continues',function(): void{$f=bFixture();bHold($f);bPublish($f,bPolicy('MANUAL',['ON_HOLD']));$t=bTicket($f);bState($f,$t,'ON_HOLD');$before=bClocks($f,$t);$future=max(array_map(fn($c)=>Time::parse($c['last_at']),$before))+10*Time::MINUTE;same(true,$f['engine']->tick($t['id'],$future));$after=bClocks($f,$t);foreach($after as $c){$prior=array_values(array_filter($before,fn($p)=>$p['id']===$c['id']))[0];if($c['metric']==='RESOLUTION'){same($prior['consumed_us'],$c['consumed_us']);}else{same(true,(int)$c['consumed_us']>(int)$prior['consumed_us']);}}});
test('SUP-005 policy revision does not rewrite historical targets calendars or completed response',function(): void{$f=bFixture();$old=bTicket($f);bReply($f,$old);$before=bClocks($f,$old);$oldPolicy=bWork($f,$old)['policy_id'];$p=bPolicy();foreach($p['targets'] as &$t){$t['FIRST']=5;}unset($t);$p['calendar']['exceptions']['2026-10-26']=[];$newPolicy=bPublish($f,$p);$new=bTicket($f);same($before,bClocks($f,$old));same($oldPolicy,bWork($f,$old)['policy_id']);same($newPolicy['id'],bWork($f,$new)['policy_id']);raises(PDOException::class,fn()=>$f['db']->execute('UPDATE support_work_policies SET spec=spec WHERE id=?',[$oldPolicy]));raises(PDOException::class,fn()=>$f['db']->execute('UPDATE support_sla_clocks SET target_us=target_us+1 WHERE id=?',[$before[0]['id']]));raises(PDOException::class,fn()=>$f['db']->execute('DELETE FROM support_sla_history WHERE clock_id=?',[$before[0]['id']]));});
test('SUP-005 risk breach and held receipts remain unique across repeated cron time',function(): void{$f=bFixture();$p=bPolicy();foreach($p['targets'] as &$v){$v=['FIRST'=>1,'NEXT'=>1,'RESOLUTION'=>1];}unset($v);bPublish($f,$p);$t=bTicket($f);$at=Time::now($f['db'])+2*Time::MINUTE;same(true,$f['engine']->tick($t['id'],$at));same(4,(int)$f['db']->execute('SELECT COUNT(*) FROM support_sla_alerts')->fetchColumn());$before=bSnapshot($f);same(true,$f['engine']->tick($t['id'],$at));same($before,bSnapshot($f));$q=new Queue($f['db']);$out=new Outbox($f['db'],$q);while($out->dispatchOne()){}$w=new Worker($f['db'],$q);(new \Hostider\Commerce\EventSink($f['db']))->register($w);(new \Hostider\Support\EventSink($f['db'],$f['config']))->register($w);(new HeldSink($f['db'],$f['config']))->register($w);while($w->once()){}$e=$f['db']->execute("SELECT payload,event_uuid FROM outbox_events WHERE event_type='support.work.held' ORDER BY id LIMIT 1")->fetch();$payload=json_decode($e['payload'],true,32,JSON_THROW_ON_ERROR);$sink=new HeldSink($f['db'],$f['config']);same('SUCCEEDED',$sink->consume($payload));same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM inbox_events WHERE consumer='support.work.held.v1' AND event_uuid=?",[$e['event_uuid']])->fetchColumn());same('FAILED',$sink->consume(array_replace($payload,['ticket_id'=>Id::uuid()])));same(0,(int)$f['db']->execute("SELECT COUNT(*) FROM identity_notifications WHERE status<>'HELD'")->fetchColumn());});
test('SUP-006 round robin is deterministic and cron does not reassign valid staff',function(): void{$f=bFixture('ROUND_ROBIN');$staff=[$f['admin']['user'],$f['staff']['user']];sort($staff,SORT_STRING);$tickets=[];foreach(range(0,3) as $n){$t=bTicket($f);$tickets[]=$t;same(true,$f['engine']->tick($t['id']));same($staff[$n%2],bWork($f,$t)['assignee_id']);} $before=$f['db']->execute('SELECT COUNT(*) FROM support_work_events')->fetchColumn();foreach($tickets as $t){same(true,$f['engine']->tick($t['id']));}same($before,$f['db']->execute('SELECT COUNT(*) FROM support_work_events')->fetchColumn());});
test('SUP-006 weighted least load uses explicit weights and UUID tie break',function(): void{$f=bFixture('LEAST_LOAD');$staff=[$f['admin']['user'],$f['staff']['user']];sort($staff,SORT_STRING);$expected=[$staff[0],$staff[1],$staff[1],$staff[0]];foreach(['HIGH','NORMAL','NORMAL','NORMAL'] as $n=>$priority){$t=bTicket($f,$priority);same(true,$f['engine']->tick($t['id']));same($expected[$n],bWork($f,$t)['assignee_id']);}same([1,2],array_values(array_unique(array_map('intval',array_column($f['db']->execute('SELECT weight FROM support_work_tickets ORDER BY weight')->fetchAll(),'weight')))));});
test('SUP-006 missing shift availability priority or expiry is fail closed',function(): void{$f=bFixture('ROUND_ROBIN',false);$t=bTicket($f,'CRITICAL');same(true,$f['engine']->tick($t['id']));same(null,bWork($f,$t)['assignee_id']);same('NO_ELIGIBLE_STAFF',bWork($f,$t)['reason']);$elig=new Eligibility($f['c']);$row=bRow($f,$t);foreach([['available'=>false],['priorities'=>['LOW']],['leaves'=>[[Time::format(Time::now($f['db'])-Time::MINUTE),Time::format(Time::now($f['db'])+60*Time::MINUTE)]]],['calendar'=>array_replace(bCalendar(),['weekly'=>array_fill(1,7,[])])]] as $changes){bRoster($f,$f['admin']['user'],$changes);same(false,$elig->eligible($row,$f['admin']['user'],Time::now($f['db'])));}bRoster($f,$f['admin']['user']);same(false,$elig->eligible($row,$f['admin']['user'],Time::now($f['db'])+11*86400*1_000_000));same(true,$f['engine']->tick($t['id']));same($f['admin']['user'],bWork($f,$t)['assignee_id']);});
