test('SUP-006 manual assignment and unassign override auto until explicit auto command',function(): void{$f=bFixture('ROUND_ROBIN');$t=bTicket($f);$result=bCommand($f,'assign',['id'=>$t['id'],'version'=>1,'assignee_id'=>$f['staff']['user']]);same(2,$result['version']);same(true,$f['engine']->tick($t['id']));same($f['staff']['user'],bWork($f,$t)['assignee_id']);bCommand($f,'assign',['id'=>$t['id'],'version'=>(int)bRow($f,$t)['version'],'assignee_id'=>null]);same(true,$f['engine']->tick($t['id']));same(null,bWork($f,$t)['assignee_id']);bCommand($f,'auto',['id'=>$t['id'],'version'=>(int)bRow($f,$t)['version']]);same(true,$f['engine']->tick($t['id']));same(true,bWork($f,$t)['assignee_id']!==null);same(409,raises(HttpError::class,fn()=>bCommand($f,'assign',['id'=>$t['id'],'version'=>1,'assignee_id'=>$f['admin']['user']]))->status);});
