test('SUP-006 real 1 4 8 PHP workers assign each ticket once with consistent RR and bounded cron',function(): void{$f=bFixture('ROUND_ROBIN');foreach([1,4,8] as $workers){$ids=[];for($n=0;$n<8;++$n){$ids[]=bTicket($f)['id'];}$before=(int)$f['db']->execute("SELECT COUNT(*) FROM support_work_events WHERE kind='ASSIGNED'")->fetchColumn();$requests=array_fill(0,$workers,['ids'=>$ids]);$race=bRace($f,$requests);$worked=array_sum(array_column($race,'worked'));same(true,$worked>0);if($workers===1){same(8,$worked);}foreach($ids as $id){$f['engine']->tick($id);}$after=(int)$f['db']->execute("SELECT COUNT(*) FROM support_work_events WHERE kind='ASSIGNED'")->fetchColumn();same($before+8,$after);foreach($ids as $id){same(1,(int)$f['db']->execute('SELECT assignment_version FROM support_work_tickets WHERE ticket_id=?',[$id])->fetchColumn());same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages WHERE ticket_id=?',[$id])->fetchColumn());}}$result=$f['engine']->run(1,1);same(1,$result['checked']);$cli=domainCli($f,['support:work','--max-tickets=1','--max-seconds=1']);same(1,$cli['checked']);same(true,$cli['test_only']);same(422,raises(HttpError::class,fn()=>$f['engine']->run(26,1))->status);});

test('SUP-005 native HTTP detail protects department customer scope and fresh confirmation rules',function(): void{$f=bFixture();$t=bTicket($f);$server=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$auth=['cookies'=>[],'csrf'=>''];try{same(401,bHttp($server,'/api/v1/admin/support-work/detail?id='.$t['id'],$auth)[0]);bLogin($server,$f['admin'],$auth);$r=bHttp($server,'/api/v1/admin/support-work/detail?id='.$t['id'],$auth);same(200,$r[0]);$settings=bHttp($server,'/api/v1/admin/support-work/settings?department_id='.$f['departments'][0],$auth);same(200,$settings[0]);same(false,str_contains($settings[2],'session_id'));$queue=bHttp($server,'/api/v1/admin/support-work/unassigned',$auth);same(200,$queue[0]);same([$t['id']],array_column($queue[1]['data'],'id'));same(2,count($r[1]['data']['clocks']));same(true,isset($r[1]['data']['clocks'][0]['remaining_business_minutes']));foreach(['subject','body','session_id','spec','customer_id'] as $hidden){same(false,str_contains($r[2],'"'.$hidden.'"'));}$other=bTicket($f,dep:$f['departments'][1],who:$f['other']);same(404,bHttp($server,'/api/v1/admin/support-work/detail?id='.$other['id'],$auth)[0]);same(404,bHttp($server,'/api/v1/client/support-work/detail?id='.$t['id'],$auth)[0]);$body=['action'=>'assign','payload'=>(object)['id'=>$t['id'],'version'=>1,'assignee_id'=>$f['admin']['user']]];same(403,bHttp($server,'/api/v1/admin/support-work/prepare',$auth,$body,csrf:false)[0]);same(405,bHttp($server,'/api/v1/admin/support-work/prepare',$auth)[0]);$before=$f['db']->execute('SELECT COUNT(*) FROM support_work_events')->fetchColumn();$prep=bHttp($server,'/api/v1/admin/support-work/prepare',$auth,$body);same(200,$prep[0]);same($before,$f['db']->execute('SELECT COUNT(*) FROM support_work_events')->fetchColumn());$body['confirmation']=(object)['id'=>$prep[1]['data']['id'],'accepted'=>true];$key=Id::uuid();$one=bHttp($server,'/api/v1/admin/support-work/execute',$auth,$body,$key);same(200,$one[0]);same($one[1]['data'],bHttp($server,'/api/v1/admin/support-work/execute',$auth,$body,$key)[1]['data']);same(409,bHttp($server,'/api/v1/admin/support-work/execute',$auth,$body)[0]);$body['payload']->assignee_id=$f['staff']['user'];same(409,bHttp($server,'/api/v1/admin/support-work/execute',$auth,$body,$key)[0]);}finally{$server->stop();}});
test('SUP-006 two native HTTP staff same version produce one assignment and explicit conflict',function(): void{$f=bFixture();$t=bTicket($f);$servers=[new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php'),new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php')];$requests=[];try{foreach([$f['admin'],$f['staff']] as $n=>$who){$auth=['cookies'=>[],'csrf'=>''];bLogin($servers[$n],$who,$auth);$body=['action'=>'assign','payload'=>(object)['id'=>$t['id'],'version'=>1,'assignee_id'=>$who['user']]];$prep=bHttp($servers[$n],'/api/v1/admin/support-work/prepare',$auth,$body);same(200,$prep[0]);$body['confirmation']=(object)['id'=>$prep[1]['data']['id'],'accepted'=>true];$requests[]=['url'=>'http://127.0.0.1:'.$servers[$n]->diagnostics()['port'].'/api/v1/admin/support-work/execute','body'=>$body,'key'=>Id::uuid(),'cookie'=>implode('; ',array_map(fn($k,$v)=>$k.'='.$v,array_keys($auth['cookies']),$auth['cookies'])),'csrf'=>$auth['csrf']];}$result=bRace($f,$requests);$status=array_column($result,'status');sort($status);same([200,409],$status);same(1,(int)bWork($f,$t)['assignment_version']);same(2,(int)bRow($f,$t)['version']);same(1,(int)$f['db']->execute("SELECT COUNT(*) FROM support_work_events WHERE ticket_id=? AND kind='ASSIGNED'",[$t['id']])->fetchColumn());}finally{foreach($servers as $server){$server->stop();}}});
test('SUP-006 native HTTP permission revoke session version and stale step-up cut access',function(): void{$f=bFixture();$t=bTicket($f);$server=new HttpTestServer(dirname(__DIR__),bEnvironment($f),__DIR__.'/commerce-router.php');$auth=['cookies'=>[],'csrf'=>''];try{bLogin($server,$f['admin'],$auth);$body=['action'=>'assign','payload'=>(object)['id'=>$t['id'],'version'=>1,'assignee_id'=>$f['admin']['user']]];$f['db']->execute('UPDATE identity_sessions SET verified_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 10 MINUTE) WHERE user_id=?',[$f['admin']['user']]);same(403,bHttp($server,'/api/v1/admin/support-work/prepare',$auth,$body)[0]);$f['db']->execute('UPDATE identity_sessions SET verified_at=UTC_TIMESTAMP(6) WHERE user_id=?',[$f['admin']['user']]);$role=$f['db']->execute("SELECT id FROM identity_roles WHERE name='Super Admin'")->fetchColumn();$f['db']->execute("DELETE FROM identity_role_permissions WHERE role_id=? AND permission='support.ticket.assign'",[$role]);same(404,bHttp($server,'/api/v1/admin/support-work/prepare',$auth,$body)[0]);$f['db']->execute('UPDATE identity_users SET identity_version=identity_version+1 WHERE id=?',[$f['admin']['user']]);same(401,bHttp($server,'/api/v1/admin/support-work/detail?id='.$t['id'],$auth)[0]);same(1,(int)bRow($f,$t)['version']);}finally{$server->stop();}});
test('F5-B additive 049 to 050 upgrade replay and old checksums are preserved',function(): void{$root=dirname(__DIR__);$db=isolatedDomainDb();$dir=$root.'/storage/f5-b-prefix-'.bin2hex(random_bytes(5));mkdir($dir,0700);$files=[];try{foreach(glob($root.'/migrations/*.php') as $p){if(basename($p)<'050'){$to=$dir.'/'.basename($p);copy($p,$to);$files[]=$to;}}same(49,count((new \Hostider\Core\Database\Migrator($db,$dir))->migrate()));$before=$db->execute('SELECT version,checksum,status FROM schema_migrations ORDER BY version')->fetchAll();$m=new \Hostider\Core\Database\Migrator($db,$root.'/migrations');same(['050_support_sla_assignment.php','051_support_sla_availability.php','052_support_mail.php','053_support_automation_incident_csat.php','054_support_ui_state.php','055_support_auto_close.php','056_support_ticket_merge.php','057_support_ticket_split.php'],$m->migrate());same([],$m->migrate());$m->assertReady();same($before,$db->execute("SELECT version,checksum,status FROM schema_migrations WHERE version<'050' ORDER BY version")->fetchAll());}finally{foreach($files as $p){unlink($p);}rmdir($dir);}});

test('SUP-006 target eligibility follows native department revoke role revoke MFA and customer grants',function(): void{
    $f=bFixture();$t=bTicket($f);$row=bRow($f,$t);$e=new Eligibility($f['c']);$user=$f['staff']['user'];same(true,$e->eligible($row,$user,Time::now($f['db'])));
    same(false,$e->eligible(array_replace($row,['customer_id'=>$f['other']['customer']]),$user,Time::now($f['db'])));same(false,$e->eligible(array_replace($row,['department_id'=>$f['departments'][1]]),$user,Time::now($f['db'])));
    foreach([false,true] as $enabled){$v=(int)$f['db']->execute('SELECT version FROM support_departments WHERE id=?',[$row['department_id']])->fetchColumn();$f['service']->command($f['admin']['reference'],'admin','member',['department_id'=>$row['department_id'],'user_id'=>$user,'version'=>$v,'enabled'=>$enabled],Id::uuid(),Id::uuid());same($enabled,$e->eligible($row,$user,Time::now($f['db'])));}
    foreach(["UPDATE identity_mfa SET enabled=FALSE WHERE user_id=?","UPDATE identity_users SET status='DISABLED' WHERE id=?"] as $sql){$f['db']->pdo->beginTransaction();try{$f['db']->execute($sql,[$user]);same(false,$e->eligible($row,$user,Time::now($f['db'])));}finally{$f['db']->pdo->rollBack();}}
    $role=$f['db']->execute("SELECT id FROM identity_roles WHERE name='Destek'")->fetchColumn();$permissions=array_column($f['db']->execute("SELECT permission FROM identity_role_permissions WHERE role_id=? AND permission<>'support.ticket.reply'",[$role])->fetchAll(),'permission');$f['c']->identity->manageRole($f['admin']['reference'],'admin',$role,'Destek',$permissions);same(false,$e->eligible($row,$user,Time::now($f['db'])));same(409,raises(HttpError::class,fn()=>bCommand($f,'assign',['id'=>$t['id'],'version'=>1,'assignee_id'=>$user]))->status);
});
test('SUP-006 confirmation binds roster revision and held sink rejects unpublished forged extra payload',function(): void{
    $f=bFixture();$t=bTicket($f);$cmd=new Commands($f['c']);$body=['action'=>'assign','payload'=>['id'=>$t['id'],'version'=>1,'assignee_id'=>$f['staff']['user']]];$prep=$cmd->command($f['admin']['reference'],'prepare',$body,Id::uuid(),Id::uuid());bRoster($f,$f['staff']['user']);$body['confirmation']=['id'=>$prep['id'],'accepted'=>true];same('WORK_CONFIRMATION_STALE',raises(HttpError::class,fn()=>$cmd->command($f['admin']['reference'],'execute',$body,Id::uuid(),Id::uuid()))->errorCode);same(null,bWork($f,$t)['assignee_id']);
    bCommand($f,'assign',$body['payload']);$event=$f['db']->execute("SELECT payload FROM outbox_events WHERE event_type='support.work.held' LIMIT 1")->fetchColumn();$p=json_decode($event,true,32,JSON_THROW_ON_ERROR);$sink=new HeldSink($f['db'],$f['config']);same('FAILED',$sink->consume($p));same('FAILED',$sink->consume(array_replace($p,['event_uuid'=>Id::uuid()])));same('FAILED',$sink->consume($p+['extra'=>true]));same(0,(int)$f['db']->execute("SELECT COUNT(*) FROM inbox_events WHERE consumer='support.work.held.v1'")->fetchColumn());same(1,(int)$f['db']->execute('SELECT COUNT(*) FROM support_messages WHERE ticket_id=?',[$t['id']])->fetchColumn());
});
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===realpath(__FILE__)){runTests();}
